#include "NMARM64Relocation.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
static uint32_t withImmediate(uint32_t op,int64_t units,unsigned bits){uint32_t field=(uint32_t)((uint64_t)units&((UINT64_C(1)<<bits)-1));return bits==26?op|field:bits==21?op|((field&3u)<<29)|((field>>2)<<5):op|(field<<5);}
static int64_t sx(uint32_t v,unsigned bits){return (v&(1u<<(bits-1)))?-(int64_t)((UINT64_C(1)<<bits)-v):(int64_t)v;}
static uint64_t decoded(uint32_t op,uint64_t pc,unsigned bits){if(bits==26)return (uint64_t)((int64_t)pc+sx(op&0x3ffffffu,26)*4);if(bits==21){uint32_t x=((op>>5)&0x7ffffu)*4+((op>>29)&3u);return (uint64_t)((int64_t)(pc&~(op&0x80000000u?UINT64_C(4095):0))+sx(x,21)*(op&0x80000000u?4096:1));}return (uint64_t)((int64_t)pc+sx((op>>5)&((1u<<bits)-1),bits)*4);}
int main(void){const uint32_t ops[]={0x14000000,0x94000000,0x54000000,0x34000000,0x35000000,0x36000000,0x37000000,0x18000000,0x58000000,0x1c000000,0x10000000,0x90000000};const unsigned widths[]={26,26,19,19,19,14,14,19,19,19,21,21};size_t checked=0;
 for(size_t i=0;i<12;i++)for(int32_t units=-1000;units<=1000;units++)if(units){uint64_t from=0x100004004,to=0x100004104;uint32_t op=withImmediate(ops[i],units,widths[i]);NMARM64RelocationResult out={0};NMARM64RelocationStatus status=NMARM64RelocateInstruction(op,from,to,from,from+4,&out);uint64_t t=decoded(op,from,widths[i]);if(t>=from&&t<from+4){assert(status==NMARM64RelocationInterior);continue;}assert(status==NMARM64RelocationOK);assert(decoded(out.instruction,to,widths[i])==t);assert(out.terminal==(i==0));checked++;}
 uint32_t branch=0;assert(NMARM64EncodeBranch(0x20000000,0x18000000,false,&branch)&&branch==0x16000000);assert(NMARM64EncodeBranch(0x20000000,0x27fffffc,true,&branch)&&branch==0x95ffffff);branch=123;assert(!NMARM64EncodeBranch(0x20000000,0x28000000,false,&branch)&&branch==123);assert(!NMARM64EncodeBranch(0,2,false,&branch));
 NMARM64RelocationResult out={123,true},saved=out;assert(NMARM64RelocateInstruction(0x14000000,0x1000,0x2000,0x1000,0x1004,&out)==NMARM64RelocationInterior);assert(out.instruction==saved.instruction&&out.terminal==saved.terminal);
 assert(NMARM64RelocateInstruction(0x17ffffff,0,0x1000,0,4,&out)==NMARM64RelocationOverflow);assert(NMARM64RelocateInstruction(0x54000010,0x1000,0x2000,0x1000,0x1004,&out)==NMARM64RelocationUnsupported);assert(NMARM64RelocateInstruction(0x14000001,0x1000,0x10000000,0x1000,0x1004,&out)==NMARM64RelocationOutOfRange);
 assert(NMARM64RelocateInstruction(0xd65f03c0,0x1000,0x2000,0x1000,0x1004,&out)==0&&out.terminal);assert(NMARM64RelocateInstruction(0xd61f0200,0x1000,0x2000,0x1000,0x1004,&out)==0&&out.terminal);assert(NMARM64RelocateInstruction(0xd503201f,0x1000,0x2000,0x1000,0x1004,&out)==0&&!out.terminal);assert(NMARM64RelocateInstruction(0xd503201f,0x1004,0x2000,0x1000,0x1004,&out)==NMARM64RelocationInvalid);
 printf("PASS: %zu decoded target-preservation checks, branch range endpoints, overflow/interior/unsupported refusal and terminal flags\n",checked);return 0;}
